const fs = require\(''fs''\);

// Generate a short page-flip sound \(white noise burst with envelope\)
const sampleRate = 22050;
const duration = 0.15; // 150ms
const numSamples = Math.floor\(sampleRate * duration\);
const numChannels = 1;
const bitsPerSample = 16;
const byteRate = sampleRate * numChannels * \(bitsPerSample / 8\);
const blockAlign = numChannels * \(bitsPerSample / 8\);
const dataSize = numSamples * blockAlign;

// WAV header
const header = Buffer.alloc\(44\);
header.write\(''RIFF'', 0\);
header.writeUInt32LE\(36 + dataSize, 4\);
header.write\(''WAVE'', 8\);
header.write\(''fmt '', 12\);
header.writeUInt32LE\(16, 16\);
header.writeUInt16LE\(1, 20\); // PCM
header.writeUInt16LE\(numChannels, 22\);
header.writeUInt32LE\(sampleRate, 24\);
header.writeUInt32LE\(byteRate, 28\);
header.writeUInt16LE\(blockAlign, 32\);
header.writeUInt16LE\(bitsPerSample, 34\);
header.write\(''data'', 36\);
header.writeUInt32LE\(dataSize, 40\);

// Audio data: filtered noise with fast attack, quick decay \(paper swoosh\)
const data = Buffer.alloc\(dataSize\);
for \(let i = 0; i < numSamples; i++\) {
    const t = i / numSamples;
    // Envelope: quick attack, smooth decay
    const envelope = Math.pow\(1 - t, 2.5\) * \(t < 0.05 ? t / 0.05 : 1\);
    // Mix of noise + low sine for body
    const noise = \(Math.random\(\) * 2 - 1\) * 0.3;
    const swoosh = Math.sin\(2 * Math.PI * \(200 + t * 800\) * \(i / sampleRate\)\) * 0.15;
    const sample = Math.max\(-1, Math.min\(1, \(noise + swoosh\) * envelope * 0.7\)\);
    const intSample = Math.floor\(sample * 32767\);
    data.writeInt16LE\(intSample, i * 2\);
}

const wav = Buffer.concat\([header, data]\);
fs.writeFileSync\(''C:/Users/david/Desktop/RANDOM/STORY_KIDS/apps/mobile/assets/sounds/page_flip.wav'', wav\);
console.log\(''Created page_flip.wav \('' + wav.length + '' bytes\)''\);
")
